import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        nextInt();
        StringBuilder out = new StringBuilder();
        while (true) {
            while (pos < buf.length && buf[pos] <= 32) pos++;
            if (pos >= buf.length) break;
            long level = 0, low = 0;
            while (pos < buf.length && buf[pos] > 32) {
                level += buf[pos++] == '(' ? 1 : -1;
                low = Math.min(low, level);
            }
            if (out.length() > 0) out.append(' ');
            out.append(level == 0 && low >= -1 ? '1' : '0');
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	nextInt()
	first := true
	for {
		s := next()
		if len(s) == 0 {
			break
		}
		level, low := 0, 0
		for _, c := range s {
			if c == '(' {
				level++
			} else {
				level--
			}
			low = min(low, level)
		}
		if !first {
			w.WriteByte(' ')
		}
		first = false
		if level == 0 && low >= -1 {
			w.WriteByte('1')
		} else {
			w.WriteByte('0')
		}
	}
	w.WriteByte('\n')
	_ = strconv.Itoa
}
